using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup so prediction pool can load it
var trainingService = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole())
        .CreateLogger<ModelTrainingService>());
trainingService.TrainAndSaveModel();

builder.Services.AddSingleton(trainingService);
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.GetModelPath());

var app = builder.Build();
app.MapControllers();
app.Run();

